import { Component, inject, signal } from '@angular/core';
import { ReactiveFormsModule, FormBuilder, Validators } from '@angular/forms';
import { NgIf } from '@angular/common';
import { Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';

interface TestUser {
  phone: string;
  password: string;
  role: 'CLIENT' | 'AGENT';
  token: string;
}

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [ReactiveFormsModule, NgIf],
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css'],
})
export class LoginComponent {
  private readonly fb = inject(FormBuilder);
  private readonly http = inject(HttpClient);
  private readonly router = inject(Router);

  readonly loading = signal(false);
  readonly error = signal('');

  readonly testUsers: TestUser[] = [
    { phone: '770000001', password: 'client123', role: 'CLIENT', token: 'test-client-token' },
    { phone: '770000002', password: 'agent123', role: 'AGENT', token: 'test-agent-token' },
  ];

  readonly form = this.fb.group({
    phone:    ['', Validators.required],
    password: ['', Validators.required],
  });

  private findTestUser(phone: string, password: string): TestUser | undefined {
    const normalizedPhone = phone.replace(/\D/g, '');
    return this.testUsers.find(user => user.phone === normalizedPhone && user.password === password);
  }

  submit(): void {
    if (this.form.invalid) return;
    this.loading.set(true);
    this.error.set('');

    const phone = this.form.value.phone ?? '';
    const password = this.form.value.password ?? '';
    const testUser = this.findTestUser(phone, password);

    if (testUser) {
      localStorage.setItem('token', testUser.token);
      localStorage.setItem('role', testUser.role);
      localStorage.setItem('phone', testUser.phone);
      this.router.navigate([testUser.role === 'AGENT' ? '/admin/wallets' : '/dashboard']);
      return;
    }

    this.http.post<{ token: string; role: string; phone: string }>(
      'http://localhost:8080/api/auth/login',
      this.form.value
    ).subscribe({
      next: ({ token, role, phone }) => {
        localStorage.setItem('token', token);
        localStorage.setItem('role', role);
        localStorage.setItem('phone', phone);
        this.router.navigate([role === 'AGENT' ? '/admin/wallets' : '/dashboard']);
      },
      error: () => {
        this.error.set('Identifiants incorrects. Veuillez reessayer.');
        this.loading.set(false);
      },
    });
  }
}

<div class="login-wrapper">
  <div class="login-card">
    <div class="brand">
      <h1>BadWallet</h1>
      <p>Web Dashboard</p>
    </div>
    <form [formGroup]="form" (ngSubmit)="submit()">
      <div class="field">
        <label>Telephone</label>
        <input formControlName="phone" placeholder="77 XXX XX XX" />
        <span class="err" *ngIf="form.get('phone')?.touched && form.get('phone')?.invalid">Numero requis.</span>
      </div>
      <div class="field">
        <label>Mot de passe</label>
        <input type="password" formControlName="password" placeholder="********" />
        <span class="err" *ngIf="form.get('password')?.touched && form.get('password')?.invalid">Mot de passe requis.</span>
      </div>
      <div class="alert" *ngIf="error()">{{ error() }}</div>
      <button type="submit" [disabled]="form.invalid || loading()" class="btn-submit">
        {{ loading() ? 'Connexion...' : 'Se connecter' }}
      </button>
    </form>
    <div class="test-credentials">
      <p>Identifiants de test :</p>
      <ul>
        <li>Client : <strong>770000001</strong> / <strong>client123</strong></li>
        <li>Agent : <strong>770000002</strong> / <strong>agent123</strong></li>
      </ul>
    </div>
  </div>
</div>
